To extend the `/healthz` endpoint to include a Redis connectivity check, you'll need to update `src/db.js` to export a Redis client and a health check function, and then update `src/server.js` to call it.

### 1. Update `src/db.js`
Add the Redis client initialization and a `redisHealthcheck` function.

```javascript
import pg from 'pg';
import { createClient } from 'redis'; // You'll need to install 'redis' or use a compatible lib
import { config } from './config.js';

// Postgres Pool
export const pool = new pg.Pool({
  connectionString: config.databaseUrl,
  max: config.databasePoolMax,
  idleTimeoutMillis: 30_000,
  connectionTimeoutMillis: 2_000,
});

pool.on('error', (err) => {
  console.error('idle client error', err);
});

// Redis Client
export const redis = createClient({ url: config.redisUrl });
redis.on('error', (err) => console.error('Redis Client Error', err));

// Connect to redis (Top-level await is supported in Node 20)
await redis.connect();

export async function healthcheck() {
  const { rows } = await pool.query('select 1 as ok');
  return rows[0].ok === 1;
}

export async function redisHealthcheck() {
  const pong = await redis.ping();
  return pong === 'PONG';
}
```

*Note: Since the project uses `redis:7` in Docker but doesn't have a redis client in `package.json` yet, you should run `npm install redis`.*

### 2. Update `src/server.js`
Update the route to check both services.

```javascript
import express from 'express';
import { config } from './config.js';
import { healthcheck, redisHealthcheck } from './db.js'; // Import redis check
import { chargeInvoice } from './billing.js';

const app = express();
app.use(express.json());

app.get('/healthz', async (_req, res) => {
  try {
    const [dbOk, redisOk] = await Promise.all([
      healthcheck(),
      redisHealthcheck()
    ]);

    if (!dbOk || !redisOk) {
      throw new Error('Subservice unhealthy');
    }

    res.json({ 
      ok: true, 
      services: { database: dbOk, redis: redisOk } 
    });
  } catch (err) {
    res.status(503).json({ 
      ok: false, 
      error: err.message 
    });
  }
});

// ... rest of file
```

